#include <cstddef>`n#include <cstdint>`n#include <corecrt.h>`nstruct _iobuf { char* _ptr; int _cnt; char* _base; int _flag; int _file; int _charbuf; int _bufsiz; char* _tmpfname; };`nusing FILE = _iobuf;`nstatic_assert(offsetof(_iobuf, _ptr) == 0x00);`nstatic_assert(offsetof(_iobuf, _cnt) == 0x04);`nstatic_assert(offsetof(_iobuf, _base) == 0x08);`nstatic_assert(offsetof(_iobuf, _flag) == 0x0c);`nstatic_assert(sizeof(_iobuf) == 0x20);`nextern "C" int __cdecl __fileno(FILE* _File);`nextern "C" unsigned int __cdecl __write(`n    int _FileHandle,`n    const char* _Buffer,`n    unsigned int _Count);`n`nextern "C" int __cdecl __flush(FILE* _File)`n{`n    int result = 0;`n`n    if (((static_cast<unsigned char>(_File->_flag) & 3U) == 2U) &&`n        ((_File->_flag & 0x108U) != 0U))`n    {`n        char* buffer = _File->_base;`n        unsigned int count =`n            static_cast<unsigned int>(`n                static_cast<int>(_File->_ptr - buffer));`n`n        if (static_cast<int>(count) > 0)`n        {`n            unsigned int requested = count;`n            int fileHandle = __fileno(_File);`n            unsigned int written = __write(fileHandle, buffer, requested);`n`n            if (written == count)`n            {`n                if (static_cast<signed char>(_File->_flag) < 0)`n                    _File->_flag &= 0xFFFFFFFDU;`n            }`n            else`n            {`n                _File->_flag |= 0x20U;`n                result = -1;`n            }`n        }`n    }`n`n    _File->_cnt = 0;`n    _File->_ptr = _File->_base;`n`n    return result;`n}`n